// Booking is only a type — a plain import keeps a runtime edge.
import { Booking } from './model.ts';
import { makeBooking } from './model.ts';
export function first(): Booking { return makeBooking(1, 'BE-201'); }

export type Booking = { id: number; lab: string };
export type Lab = { code: string };
export const makeBooking = (id: number, lab: string): Booking => ({ id, lab });
export const MAX = 40;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { first } from '../src/app.ts';
test('first builds a booking', () => { assert.equal(first().lab, 'BE-201'); });

