// A type and a value in one import — the type makes it TS1484.
import { Lab, MAX } from './model.ts';
export const lab: Lab = { code: 'BE-' + MAX };

export type Booking = { id: number; lab: string };
export type Lab = { code: string };
export const makeBooking = (id: number, lab: string): Booking => ({ id, lab });
export const MAX = 40;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { lab } from '../src/app.ts';
test('lab is built from the value', () => { assert.equal(lab.code, 'BE-40'); });

